args.source:
export default behaviour({
  name: 'Limit',
  state: { last: -100 },
  inputs: ['hit'],
  outputs: ['ding'],
  on: {
    hit() {
      const t = this.now();
      if (t - this.state.last >= 0.5) { this.state.last = t; this.emit('ding'); }
    }
  }
});

export default behaviour({
  name: 'Spike',
  state: { hp: 100, on: false, ticking: false },
  inputs: ['enter', 'exit'],
  outputs: ['hp', 'died'],
  on: {
    enter() { this.state.on = true; if (!this.state.ticking) { this.state.ticking = true; this.after(0.25, 'tick'); } },
    exit() { this.state.on = false; }
  },
  tick() {
    if (!this.state.on) { this.state.ticking = false; return; }
    this.state.hp = Math.max(0, this.state.hp - 10);
    if (this.state.hp <= 0) { this.state.hp = 100; this.state.on = false; this.state.ticking = false; this.emit('died'); return; }
    this.after(0.25, 'tick');
  }
});

