export default behaviour({
  name: 'PauseKey',
  state: { paused: false },
  inputs: ['key'],
  outputs: ['pause', 'resume'],
  on: {
    key() {
      this.state.paused = !this.state.paused;
      this.emit(this.state.paused ? 'pause' : 'resume');
    }
  }
});

